const tour = document.querySelector('#tour');
const meeting = document.querySelector('#meeting-point');
const meetingPoints = {
  ceramics: '10:00 在陶艺馆门口集合。',
  clocks: '14:00 在钟表馆咨询台集合。',
  prints: '16:00 在版画馆大厅集合。',
};

tour.addEventListener('change', () => {
  meeting.textContent = meetingPoints[tour.selectedIndex] ?? '请先选择导览场次。';
});

const form = document.querySelector('#submission-form');
const titleField = document.querySelector('#work-title');
const feedback = document.querySelector('#submission-feedback');

form.addEventListener('submit', (event) => {
  event.preventDefault();
  const title = titleField.value;
  if (title.length === 0) {
    feedback.textContent = '请填写作品标题。';
    return;
  }
  if (title.length < 3) {
    feedback.textContent = '标题至少需要 3 个字符。';
    return;
  }
  feedback.textContent = '作品标题《' + title + '》已通过检查。';
});

const tableName = document.querySelector('#table-name');
const tableCard = document.querySelector('#table-card');

tableName.addEventListener('keydown', (event) => {
  tableCard.textContent = tableName.value;
});

const button = document.querySelector('#make-list');
const list = document.querySelector('#days');
button.addEventListener('click', () => {
  for (let day = 1; day <= 5; day++) {
    const item = document.createElement('li');
    item.textContent = `第 ${day} 天`;
    list.append(item);
  }
});

const songList = document.querySelector('#song-list');
const selectedSong = document.querySelector('#selected-song');
const addSong = document.querySelector('#add-song');
const extraSong = document.querySelector('#extra-song');

addSong.addEventListener('click', () => {
  songList.append(extraSong.content.cloneNode(true));
  addSong.disabled = true;
});

songList.addEventListener('click', (event) => {
  const song = event.target.matches('button[data-title]') ? event.target : null;
  if (song) {
    selectedSong.textContent = song.dataset.title;
  }
});
